#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the Matt wizard playbook. Human-run only.
# Adapted library: explicit dotenv limits, fail-closed input, truthful partial
# status, regular-file atomic writes, secret submission confirmation.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set +x # Never trace human-entered values. Do not run this script in an agent-observed terminal.
set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WIZARD_GITHUB_REPO="${WIZARD_GITHUB_REPO:-}" # Author pins verified owner/repo before CI writes.
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
WRITTEN_VAR=()    # public variable NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)
_WIZARD_TMP=""
_cleanup() { if [[ -n "$_WIZARD_TMP" ]]; then rm -f -- "$_WIZARD_TMP"; fi; }
trap _cleanup EXIT
trap 'printf "\nWizard interrupted; completed writes remain, later stages were not run.\n" >&2; exit 130' INT
trap 'printf "\nWizard stopped; completed writes remain, later stages were not run.\n" >&2; exit 143' TERM

_valid_key() { [[ "$1" =~ ^[A-Z_][A-Z0-9_]*$ ]]; }
_eof() { printf '\nInput ended; procedure incomplete.\n' >&2; exit 1; }

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || _eof
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || _eof
  [[ "$reply" =~ ^([Yy]|[Yy][Ee][Ss])$ ]]
}

# _existing KEY reads only unambiguous single-line literals; never source/eval .env.
# The writer dialect is literal single-quoted values without apostrophe or CR/LF.
_existing() {
  _valid_key "$1" || return 1
  [[ -f "$ENV_FILE" && ! -L "$ENV_FILE" ]] || return 1
  local line value
  line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" != *\'* && "$value" != *$'\r'* && "$value" != *$'\n'* ]] || return 1
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" != *[\\\$\"]* && "$value" != *$'\r'* ]] || return 1
  else
    # Unknown quoting, comments, whitespace or interpolation must be re-entered.
    [[ "$value" != *[[:space:]\\\$\"\'#]* ]] || return 1
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Any EOF, including an unterminated partial line, fails closed.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  _valid_key "$key" || { warn "invalid variable name"; return 1; }
  input=""
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )); then _eof; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  _valid_key "$key" || { warn "invalid variable name"; return 1; }
  input=""
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )); then _eof; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE atomically upserts one literal single-line dotenv value.
# Supports spaces, $, #, backslashes and double quotes. Apostrophe/CR/LF require
# the human's target-parser-aware editor/tool; reject before creating any file.
# Never shell-escape dotenv, source it, follow a symlink or truncate in place.
write_env() {
  local key="$1" value="$2" tmp mode="600" before="missing" line rhs
  _valid_key "$key" || { warn "invalid variable name"; return 1; }
  if [[ "$value" == *\'* || "$value" == *$'\n'* || "$value" == *$'\r'* ]]; then
    warn "not written: apostrophe or multiline value needs your target-parser-aware dotenv editor; keep the original value private"
    return 1
  fi
  [[ ! -L "$ENV_FILE" ]] || { warn "not written: ENV_FILE is a symlink; choose a verified regular file"; return 1; }
  if [[ -e "$ENV_FILE" ]]; then
    [[ -f "$ENV_FILE" ]] || { warn "not written: ENV_FILE is not a regular file"; return 1; }
    # Refuse multiline/ambiguous quoted assignments rather than remove a key
    # from inside somebody else's multiline value. This is a narrow dialect.
    while IFS= read -r line || [[ -n "$line" ]]; do
      if [[ "$line" =~ ^[[:space:]]*(export[[:space:]]+)?[A-Za-z_][A-Za-z0-9_]*[[:space:]]*=(.*)$ ]]; then
        rhs="${BASH_REMATCH[2]}"
        rhs="${rhs#"${rhs%%[![:space:]]*}"}"
        if [[ "$rhs" == "'" || "$rhs" == '"' ]]; then
          warn "not written: existing multiline dotenv needs your target-parser-aware editor"; return 1
        fi
        if [[ "$rhs" == \'* && "$rhs" != *\' || "$rhs" == \"* && "$rhs" != *\" || "$rhs" == \`* ]]; then
          warn "not written: existing dotenv quoting needs your target-parser-aware editor"
          return 1
        fi
      fi
    done < "$ENV_FILE"
    mode=$(stat -c '%a' "$ENV_FILE" 2>/dev/null || stat -f '%Lp' "$ENV_FILE") || return 1
    before=$(cksum < "$ENV_FILE") || return 1
  fi
  tmp=$(mktemp "${ENV_FILE}.wizard.XXXXXX") || return 1
  _WIZARD_TMP="$tmp"
  chmod "$mode" "$tmp" || return 1
  if [[ -e "$ENV_FILE" ]]; then
    # Keys are validated before becoming the match expression.
    awk -v key="$key" '$0 !~ "^[[:space:]]*(export[[:space:]]+)?" key "[[:space:]]*=" { print }' "$ENV_FILE" > "$tmp" || return 1
  fi
  printf "%s='%s'\n" "$key" "$value" >> "$tmp" || return 1
  if [[ -L "$ENV_FILE" ]] || { [[ "$before" == "missing" ]] && [[ -e "$ENV_FILE" ]]; } || { [[ "$before" != "missing" ]] && [[ ! -f "$ENV_FILE" || "$(cksum < "$ENV_FILE")" != "$before" ]]; }; then
    warn "not written: dotenv changed while editing; rerun and reconcile"
    return 1
  fi
  mv -f -- "$tmp" "$ENV_FILE" || return 1
  _WIZARD_TMP=""
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  _valid_key "$name" || { warn "invalid GitHub name"; return 1; }
  if [[ -z "$WIZARD_GITHUB_REPO" ]]; then
    SKIPPED+=("GitHub $name (repository destination not configured)")
    warn "skipped GitHub $name: no verified repository destination"; return 0
  fi
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if ! confirm "Submit secret $name to GitHub repository $WIZARD_GITHUB_REPO?"; then
      SKIPPED+=("GitHub secret $name (submission declined)"); return 0
    fi
    if printf '%s' "$value" | gh secret set "$name" --repo "$WIZARD_GITHUB_REPO" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  _valid_key "$name" || { warn "invalid GitHub name"; return 1; }
  if [[ -z "$WIZARD_GITHUB_REPO" ]]; then
    SKIPPED+=("GitHub $name (repository destination not configured)")
    warn "skipped GitHub $name: no verified repository destination"; return 0
  fi
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if ! confirm "Submit public variable $name to GitHub repository $WIZARD_GITHUB_REPO?"; then
      SKIPPED+=("GitHub variable $name (submission declined)"); return 0
    fi
    if gh variable set "$name" --repo "$WIZARD_GITHUB_REPO" --body "$value" >/dev/null 2>&1; then
      WRITTEN_VAR+=("$name")
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  if (( ${#SKIPPED[@]} )) || (( _STAGE_INDEX != TOTAL_STAGES )); then
    printf '\n%s%s  Procedure incomplete%s\n' "$BOLD" "$YELLOW" "$RESET"
  else
    printf '\n%s%s  ✓ Planned stages completed%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  (( ${#WRITTEN_VAR[@]} )) && note "set ${#WRITTEN_VAR[@]} GitHub variable(s): ${WRITTEN_VAR[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
  if (( ${#SKIPPED[@]} )) || (( _STAGE_INDEX != TOTAL_STAGES )); then return 2; fi
  return 0
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=1

# Set WIZARD_GITHUB_REPO="verified-owner/verified-repo" only if CI storage is approved.
banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
